styles:
body {
    font-family: 'Roboto Condensed', sans-serif;
    line-height: 1.6;
    color: #FFFFFF;
    margin: 0;
    padding: 0;
    background-color: #000000;
}
.container {
    max-width: 900px;
    margin: 20px auto;
    padding: 20px 30px;
}
h1, h2, h3, h4 {
    color: #FFFFFF;
    font-weight: 700;
    text-transform: uppercase;
    font-family: 'Roboto Condensed', sans-serif;
}
h1 {
    font-size: 2.5em;
    border-bottom: 3px solid #330000;
    padding-bottom: 15px;
    margin-bottom: 25px;
    text-align: center;
    letter-spacing: 1px;
}
h2 {
    font-size: 1.8em;
    margin-top: 30px;
    border-left: 5px solid #cc0000;
    padding-left: 10px;
}
h3 {
    font-size: 1.3em;
    margin-top: 20px;
    color: #ff3333;
}
p {
    margin-bottom: 15px;
    color: #FFFFFF;
}
a {
    color: #ffaa33;
    text-decoration: none;
}
a:hover {
    color: #ffd077;
    text-decoration: underline;
}

/* ----------------------------------------------------------------
   FEATURE CARDS — for Google AI Pro (gold/premium) benefit list
---------------------------------------------------------------- */
.feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 14px;
    margin: 22px 0;
}
.feature-card {
    background: linear-gradient(160deg, #1a1200 0%, #0d0d0d 100%);
    border: 1px solid #7a5500;
    border-top: 3px solid #ffcc00;
    border-radius: 6px;
    padding: 16px 18px;
}
.feature-card .f-title {
    font-family: 'Roboto Condensed', sans-serif;
    font-weight: 700;
    color: #ffcc00;
    font-size: 1em;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    margin-bottom: 6px;
    display: block;
}
.feature-card .f-desc {
    color: #e8e8e8;
    font-size: 0.93em;
    line-height: 1.5;
}

/* ----------------------------------------------------------------
   FEATURE LIST (SIMPLE) — for Google AI Plus benefit list (cooler tone)
---------------------------------------------------------------- */
.feature-list-simple {
    margin: 20px 0;
    border: 1px solid #003344;
    border-radius: 6px;
    overflow: hidden;
}
.feature-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 16px;
    background-color: #061a1f;
    border-bottom: 1px solid #003344;
}
.feature-row:last-child { border-bottom: none; }
.feature-row .f-icon {
    color: #33ccff;
    font-weight: 700;
    font-size: 1.1em;
    flex-shrink: 0;
    line-height: 1.5;
}
.feature-row .f-body strong {
    color: #66d9ff;
    display: block;
    margin-bottom: 2px;
    font-size: 0.98em;
}
.feature-row .f-body span {
    color: #dcecef;
    font-size: 0.92em;
}

/* ----------------------------------------------------------------
   BADGE GRID — for eligible product lines
---------------------------------------------------------------- */
.badge-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin: 20px 0;
}
.badge-item {
    background-color: #1a0000;
    border: 1px solid #cc0000;
    border-radius: 20px;
    padding: 8px 18px;
    font-size: 0.9em;
    color: #ffffff;
    display: flex;
    align-items: center;
    gap: 8px;
}
.badge-item .b-name {
    font-weight: 700;
    color: #ff5555;
    text-transform: uppercase;
    font-size: 0.85em;
}
.badge-item .b-desc {
    color: #d8d8d8;
}

/* ----------------------------------------------------------------
   STEP TIMELINE — for the 6-step redemption process
---------------------------------------------------------------- */
.timeline {
    position: relative;
    margin: 24px 0;
    padding-left: 42px;
}
.timeline::before {
    content: "";
    position: absolute;
    left: 15px;
    top: 6px;
    bottom: 6px;
    width: 2px;
    background: linear-gradient(#cc0000, #ffaa33);
}
.timeline-step {
    position: relative;
    margin-bottom: 22px;
}
.timeline-step:last-child { margin-bottom: 0; }
.timeline-step::before {
    content: attr(data-step);
    position: absolute;
    left: -42px;
    top: 0;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: linear-gradient(135deg, #cc0000, #7a0000);
    color: #fff;
    font-weight: 700;
    font-family: 'Roboto Condensed', sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.95em;
    border: 2px solid #ffaa33;
}
.timeline-step .t-title {
    color: #ffcc00;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 1em;
    margin-bottom: 4px;
    display: block;
}
.timeline-step .t-desc {
    color: #f0f0f0;
    font-size: 0.95em;
}
